"""Small conservative XML minifier used by the CLI implementation."""
import re


_TOKEN = re.compile(r"<!--.*?-->|<!\[CDATA\[.*?\]\]>|<\?.*?\?>|<![^>]*>|<[^>]*>|[^<]+", re.S)


