    # can be significant. The parser retains it when the parent already had
    # character data, while whitespace-only element content is discarded.
    stack = []  # [tag, inherited_mixed_content, has_character_data]
    for match in _TOKEN.finditer(source):
        token = match.group(0)
        from_cdata = token.startswith("<![CDATA[")
