            comment_space = bool(
                (out and not out[-1].startswith("<") and source[:match.start()].endswith((" ", "\n", "\r", "\t")))
                or source[match.end():match.end()+1].isspace()
            )
            continue
        if token.startswith("<?"):
            out.append(token)
            continue
        if token.isspace() and out and out[-1].lower().startswith("<?xml"):
            # The declaration is not part of the document's whitespace
            # content; discard its separator before the root element.
            continue
        if token.startswith("<![CDATA["):
            # CDATA content becomes ordinary character data when the wrapper
            # is removed, so escape characters that would otherwise be markup.
            token = token[9:-3].replace("&", "&amp;").replace("<", "&lt;")
