                    stack.append([tag_match.group(1), inherited, False])
            if token.endswith("/>"):
                token = re.sub(r"\s+/>$", "/>" , token)
            if token.startswith("</") and out and out[-1].startswith("<") and not out[-1].startswith("<!"):
